import numpy as np
x=np.load('source_pixels.npz')['rgb'].astype(int)
# Check hypothesis moving object is red mallet, blue is static. Extract red mask components and compare. Print red thresholds
for fi in [0,8,16,24,32,36,40,44,48,60,95]:
 f=x[fi];r,g,b=f[...,0],f[...,1],f[...,2]
 for nm,m in [('red',(r-g>50)&(r-b>30)&(r>120)),('redpink',(r-g>30)&(r-b>10)&(r>160)&(g<190)),('brightred',(r>180)&(g<150)&(b<180))]:
  ys,xs=np.where(m)
  if len(xs): print(fi,nm,len(xs),(xs.min(),ys.min(),xs.max(),ys.max()),tuple(np.round([xs.mean(),ys.mean()],1)))
