/bin/bash -c "python - <<'PY'
import numpy as np
x=np.load('source_pixels.npz')['rgb'].astype(int)
# Track template from frame0 at object A box via normalized SSD allowing global shifts and maybe brightness
for name,box in [('A',(100,73,121,87)),('B',(135,61,153,73)),('C',(162,53,174,66)),('D',(63,91,76,100))]:
 x0,y0,x1,y1=box; a=x[0,y0:y1,x0:x1]
 print('\\n',name)
 for fi in [0,4,8,12,16,20,24,28,30,32,34,36,38,40,44,48,52,60]:
  best=(1e9,None,None)
  for yy in range(max(0,y0-30),min(144-(y1-y0),y0+30)):
   for xx in range(max(0,x0-70),min(256-(x1-x0),x0+20)):
    b=x[fi,yy:yy+(y1-y0),xx:xx+(x1-x0)]
    s=((a-b)**2).mean()
    if s<best[0]: best=(s,(xx,yy),b.mean((0,1)))
  print(fi,round(best[0],1),best[1],np.round(best[2],1))
PY"
